private IdempotencyService.Stored doReportRainfall(long zoneId, ReportRainfallRequest request) {
    repository.findZoneByIdForUpdate(zoneId).orElseThrow(...404...);
    LocalDateTime hour = request.hourStart();
    if (hour.getMinute() != 0 || hour.getSecond() != 0 || hour.getNano() != 0) {
        throw ApiException.badRequest("RAINFALL_HOUR_NOT_ALIGNED", "雨量小时起点须为UTC整点: " + hour);
    }
    requireFinite(request.rainfallMm(), "rainfallMm");
    var existing = repository.findRainfall(zoneId, hour);
    if (existing.isEmpty()) {
        if (request.expectedVersion() != 0) {
            throw ApiException.conflict("VERSION_CONFLICT", "雨量记录不存在，expectedVersion须为0: " + request.expectedVersion());
        }
        long id = repository.insertRainfall(zoneId, hour, request.rainfallMm());
        return json(201, new RainfallResponse(id, zoneId, hour, request.rainfallMm(), 1, false, false));
    }
    RainfallRow row = existing.get();
    if (Double.compare(row.rainfallMm(), request.rainfallMm()) == 0) {
        // 同测区同小时同值重放：返回既有记录，不占新版本
        return json(200, new RainfallResponse(row.id(), zoneId, hour, row.rainfallMm(), row.version(), true, false));
    }
    if (request.expectedVersion() != row.version()) {
        throw ApiException.conflict("VERSION_CONFLICT", "雨量更正版本冲突: expected=" + request.expectedVersion() + ", current=" + row.version());
    }
    repository.updateRainfall(row.id(), request.rainfallMm(), row.version() + 1);
    return json(200, new RainfallResponse(row.id(), zoneId, hour, request.rainfallMm(), row.version() + 1, false, true));
}
