/** 此前24个完整小时的雨量窗口。 */
private record RainfallWindow(LocalDateTime start, boolean complete, Double sum, List<LocalDateTime> missingHours) {}

private RainfallWindow rainfallWindow(long zoneId, LocalDateTime at) {
    LocalDateTime end = at.truncatedTo(ChronoUnit.HOURS);  // wait — "此前24个完整小时": buckets [floor(at)-24h, floor(at))
    LocalDateTime start = end.minusHours(24);
    List<RainfallRow> rows = repository.findRainfallByZoneBetween(zoneId, start, end);
    Map<LocalDateTime, Double> byHour = rows.stream().collect(toMap(RainfallRow::hourStart, RainfallRow::rainfallMm));
    List<LocalDateTime> missing = new ArrayList<>();
    double sum = 0;
    for (int i = 0; i < 24; i++) {
        LocalDateTime h = start.plusHours(i);
        Double v = byHour.get(h);
        if (v == null) missing.add(h); else sum += v;
    }
    return new RainfallWindow(start, missing.isEmpty(), missing.isEmpty() ? sum : null, missing);
}
