private SafetyEvaluation evaluateResumptionSafety(ChainRow chain, ZoneRow zone, LocalDateTime evaluatedAt) {
    // 策略版本（同一事务快照）
    List<StrategyRow> strategies = repository.findStrategiesByZone(chain.zoneId());
    StrategyRow atEval = strategies.stream()
        .filter(s -> !s.effectiveFrom().isAfter(evaluatedAt))
        .max(comparing effectiveFrom then version) or null;

    LocalDateTime windowStart = chain.triggeredAt();
    Double rainfallSum = null; LocalDateTime rainfallStart = null;
    boolean reduction = false; Integer strategyVersion = null;
    double safetyThreshold = zone.safetyHourlyRate();

    if (atEval != null) {
        strategyVersion = atEval.version();
        // 雨量窗口
        RainfallWindow window = rainfallWindow(zone.id(), evaluatedAt);
        if (!window.complete()) {
            throw 422 RAINFALL_DATA_INSUFFICIENT "... first missing=" + window.missingHours().get(0);
        }
        rainfallStart = window.start(); rainfallSum = window.sum();
        reduction = rainfallSum >= atEval.rainfall24hThreshold();
        safetyThreshold = atEval.yellowRate() * (reduction ? atEval.reductionFactor() : 1.0);
        // 变严边界
        LocalDateTime stricterAt = latestStricterBoundary(strategies, evaluatedAt);
        if (stricterAt != null && stricterAt.isAfter(windowStart)) windowStart = stricterAt;
        if (evaluatedAt.isBefore(windowStart.plusHours(RECOVERY_WINDOW_HOURS))) {
            throw 422 SAFETY_WINDOW_RESTARTED "策略变严后安全计时重新累计，生效后未满24小时";
        }
    }

    List<ReadingRow> window = readings filter (windowStart, evaluatedAt];
    if (window.isEmpty()) throw 422 NO_MONITORING_DATA;
    // per-reading check
    List<Map> details...
    for (row : window) {
        double threshold;
        Integer rowVersion = null;
        if (atEval != null) {
            StrategyRow v = strategyEffectiveAt(strategies, row.measuredAt());
            if (v != null) { threshold = v.yellowRate() * (reduction ? v.reductionFactor() : 1.0); rowVersion = v.version(); }
            else threshold = zone.safetyHourlyRate();
